function dcV3InstallTooltips(){if(!dcV3Root)return;const root=dcV3Root,previous=root.__dcV3TooltipHandlers;if(previous){root.removeEventListener("pointerover",previous.over);root.removeEventListener("pointerout",previous.out);root.removeEventListener("focusin",previous.focusin);root.removeEventListener("focusout",previous.focusout);window.removeEventListener("scroll",previous.viewport,true);window.removeEventListener("resize",previous.viewport)}const inside=(node,related)=>!!related&&(related===node||node.contains(related));const handlers={over:event=>{const node=dcV3TooltipNode(event);if(!node||!root.contains(node)||inside(node,event.relatedTarget))return;dcV3ShowTooltip(node)},out:event=>{const node=dcV3TooltipNode(event);if(!node||inside(node,event.relatedTarget)||node.matches(":focus"))return;dcV3HideTooltip()},focusin:event=>{const node=dcV3TooltipNode(event);if(node&&root.contains(node))dcV3ShowTooltip(node)},focusout:event=>{const node=dcV3TooltipNode(event);if(node&&!inside(node,event.relatedTarget))dcV3HideTooltip()},viewport:()=>dcV3HideTooltip()};root.addEventListener("pointerover",handlers.over);root.addEventListener("pointerout",handlers.out);root.addEventListener("focusin",handlers.focusin);root.addEventListener("focusout",handlers.focusout);window.addEventListener("scroll",handlers.viewport,true);window.addEventListener("resize",handlers.viewport);root.__dcV3TooltipHandlers=handlers}
function dcV3DestroyTooltips(root){const handlers=root&&root.__dcV3TooltipHandlers;if(handlers){root.removeEventListener("pointerover",handlers.over);root.removeEventListener("pointerout",handlers.out);root.removeEventListener("focusin",handlers.focusin);root.removeEventListener("focusout",handlers.focusout);window.removeEventListener("scroll",handlers.viewport,true);window.removeEventListener("resize",handlers.viewport);delete root.__dcV3TooltipHandlers}dcV3HideTooltip();if(dcV3TooltipLayer&&dcV3TooltipLayer.parentNode)dcV3TooltipLayer.parentNode.removeChild(dcV3TooltipLayer);dcV3TooltipLayer=null}
const dcV3Money=v=>{if(v==null||v===""||v==="--")return "--";const n=Number(v);return Number.isFinite(n)?"¥"+n.toLocaleString("zh-CN",{minimumFractionDigits:2,maximumFractionDigits:2}):"--"};
const dcV3Pct=v=>{if(v==null||v===""||v==="--")return "--";const n=Number(v);return Number.isFinite(n)?(n*100).toFixed(2)+"%":"--"};
const dcV3Num=v=>{const n=Number(v);return Number.isFinite(n)?n:0};
const dcV3Esc=v=>encodeURIComponent(v==null?"":String(v));
const dcV3Query=p=>Object.keys(p).filter(k=>p[k]!=null&&p[k]!=="").map(k=>encodeURIComponent(k)+"="+encodeURIComponent(p[k])).join("&");
const dcV3ApiBase="";
const dcV3Data=x=>{const d=x&&x.data;return d&&typeof d==="object"&&!Array.isArray(d)?d:{items:Array.isArray(d)?d:[]}};
const dcV3Rows=x=>{const d=dcV3Data(x),r=d.items||d.rows||d.list||d;return Array.isArray(r)?r:[]};
const dcV3Meta=x=>{const d=dcV3Data(x);return x&&x.meta||d.meta||{}};
const dcV3Summary=x=>{const d=dcV3Data(x);return d.summary||x&&x.summary||{}};
const dcV3Error=e=>{const s=e&&e.status;return s===401?"系统登录已过期，请返回系统重新进入渠道详情。":s===403?"当前账号没有渠道详情权限。":e&&e.message||"渠道详情数据加载失败"};
const dcV3StatusLabel=v=>v==="NORMAL"?"正常":v==="PARTIAL"?"部分数据":v||"--";
const dcV3PeriodLabel=()=>dcV3State.dateFrom+" 至 "+dcV3State.dateTo;
const dcV3SortValue=(row,key)=>{const value=row&&row[key];if(key.endsWith("_amount")||["arpu","arppu","registration_count","account_count","payer_count"].includes(key))return dcV3Num(value);return String(value||"").toLocaleLowerCase()};
const dcV3SortIndicator=key=>dcV3State.projectSortKey!==key?"◆":dcV3State.projectSortDirection==="asc"?"▲":"▼";
function dcV3SortRows(rows,key,direction){return rows.slice().sort((a,b)=>{const av=dcV3SortValue(a,key),bv=dcV3SortValue(b,key),n=typeof av==="number"&&typeof bv==="number"?av-bv:String(av).localeCompare(String(bv),"zh-CN");return direction==="asc"?n:-n})}
function dcV3Iso(v){return v instanceof Date?v.toISOString().slice(0,10):String(v||"").slice(0,10)}
function dcV3InitDates(){const now=new Date(),end=dcV3Iso(now),start=dcV3Iso(new Date(now.getFullYear(),now.getMonth(),1)),q=new URLSearchParams(location.search);dcV3State.dateFrom=q.get("date_from")||start;dcV3State.dateTo=q.get("date_to")||end;dcV3State.search=q.get("search")||"";dcV3State.status=q.get("status")||"";dcV3State.metric=q.get("metric")||"registration_count";dcV3State.view=q.get("view")||"list";return q}
function dcV3Url(extra){const q=new URLSearchParams(location.search);["date_from","date_to","search","status","metric","channel_id","project_id","package_id","promoter_id","view"].forEach(k=>q.delete(k));const values={date_from:dcV3State.dateFrom,date_to:dcV3State.dateTo,search:dcV3State.search,status:dcV3State.status,metric:dcV3State.metric,view:dcV3State.view};if(dcV3State.selected)values.channel_id=dcV3State.selected.channel_id;if(dcV3State.selectedProject)values.project_id=dcV3State.selectedProject.project_id;if(dcV3State.selectedProject&&dcV3State.selectedPackage)values.package_id=dcV3State.selectedPackage.package_id;if(dcV3State.selectedAccount)values.promoter_id=dcV3State.selectedAccount.promoter_id;Object.assign(values,extra||{});Object.keys(values).forEach(k=>{if(values[k])q.set(k,values[k])});history.replaceState(null,"","?"+q.toString())}
async function dcV3Fetch(path,options={}){const r=await fetch(dcV3ApiBase+path,{credentials:"same-origin",headers:{Accept:"application/json",...(options.headers||{})},...options});const j=await r.json().catch(()=>({}));if(!r.ok){const e=new Error(j.detail||j.message||("请求失败（"+r.status+"）"));e.status=r.status;throw e}return j}
function dcV3Layout(main){return `<div class="dc-proto-page">${main}</div>`}
function dcV3Dates(){return `<div class="date-picker dc-v3-tip" tabindex="0" data-tooltip="${dcV3Attr(dcV3Tips.date)}" aria-label="日期范围：${dcV3Attr(dcV3Tips.date)}"><span class="dc-v3-range-anchor" data-v3-date-picker></span></div>`}
function dcV3DatePresets(){const today=Me(),yesterday=Me().subtract(1,"d"),weekStart=Me().startOf("w"),lastWeekStart=Me().subtract(1,"w").startOf("w"),lastWeekEnd=Me().subtract(1,"w").endOf("w"),monthStart=Me().startOf("month"),lastMonth=Me().subtract(1,"month");return [{label:"昨日",value:[yesterday,yesterday]},{label:"今日",value:[today,today]},{label:"上周",value:[lastWeekStart,lastWeekEnd]},{label:"本周",value:[weekStart,today]},{label:"上月",value:[lastMonth.startOf("month"),lastMonth.endOf("month")]},{label:"本月",value:[monthStart,today]},{label:"最近30天",value:[Me().subtract(29,"d"),today]},{label:"最近90天",value:[Me().subtract(89,"d"),today]}]}
function dcV3UnmountDatePickers(){dcV3DateRoots.forEach(root=>{try{root.unmount()}catch(e){}});dcV3DateRoots=[]}
function dcV3MountDatePicker(){const nodes=dcV3Root&&dcV3Root.querySelectorAll("[data-v3-date-picker]");if(!nodes||!nodes.length||typeof Dn==="undefined"||typeof Tr==="undefined"||!Tr.RangePicker)return;dcV3UnmountDatePickers();nodes.forEach(node=>{const root=Dn.createRoot(node);dcV3DateRoots.push(root);root.render(C.jsx(Tr.RangePicker,{size:"small",style:{width:240},value:dcV3State.dateFrom&&dcV3State.dateTo?[Me(dcV3State.dateFrom),Me(dcV3State.dateTo)]:null,placeholder:["开始日期","结束日期"],allowClear:false,presets:dcV3DatePresets(),onChange:value=>{if(!value||value.length!==2)return;const from=value[0].format("YYYY-MM-DD"),to=value[1].format("YYYY-MM-DD");if(from===dcV3State.dateFrom&&to===dcV3State.dateTo)return;dcV3State.dateFrom=from;dcV3State.dateTo=to;dcV3Url();dcV3ReloadCurrent()}}))})}
function dcV3ApplyFieldTips(){const labels=[["推广员姓名","promoter_name"],["渠道账号","promoter_account"],["新付费总额","new_paid_amount"],["新付费数","new_paid_count"],["新账号数","new_account_count"],["活跃账号数","active_account_count"],["付费总额","paid_amount"],["付费数","paid_count"],["应结出流水","settlement"],["注册账号","registration_count"],["渠道流水","revenue"],["放出点位","release_point"],["接入点位","access_point"],["点位差","point_diff"],["项目数","project_count"],["账号数","account_count"],["合作主体","company"],["项目名称","project_count"],["方向","direction"],["平台","platform"],["渠道","channel"],["ARPU","arpu"],["ARPPU","arppu"]];const nodes=dcV3Root.querySelectorAll("th,.kpi label");nodes.forEach(node=>{if(node.classList.contains("dc-v3-tip")||node.querySelector(".dc-v3-tip"))return;const text=String(node.textContent||"").replace(/[◆▲▼?]/g,"").trim();const hit=labels.find(([label])=>text===label)||labels.find(([label])=>text.endsWith(label));if(!hit)return;const tip=dcV3Tips[hit[1]]||"";node.classList.add("dc-v3-tip");node.setAttribute("tabindex","0");node.setAttribute("data-tooltip",tip);node.setAttribute("aria-label",text+"："+tip);node.insertAdjacentHTML("beforeend","<i aria-hidden=\"true\">?</i>")})}
function dcV3EnsurePromoterNameColumn(){const buttons=dcV3Root.querySelectorAll("[data-v3-account]");if(!buttons.length)return;const table=buttons[0].closest("table");if(!table)return;const headers=Array.from(table.querySelectorAll("thead th"));if(headers.some(node=>String(node.textContent||"").trim()==="推广员姓名"))return;const accountHeader=headers.find(node=>String(node.textContent||"").replace(/[◆▲▼?]/g,"").trim()==="渠道账号");if(!accountHeader)return;accountHeader.insertAdjacentHTML("afterend",`<th>${dcV3Tip("推广员姓名","promoter_name")}</th>`);buttons.forEach(button=>{const account=dcV3State.accounts.find(row=>row.promoter_id===decodeURIComponent(button.dataset.v3Account));const cell=button.closest("td");if(!cell)return;cell.insertAdjacentHTML("afterend",`<td>${dcV3Attr(account&&account.promoter_name||"--")}</td>`)})}
function dcV3InstallAccountClick(){if(!dcV3Root)return;const previous=dcV3Root.__dcV3AccountClick;if(previous)dcV3Root.removeEventListener("click",previous,true);const handler=event=>{const button=event.target&&event.target.closest&&event.target.closest("[data-v3-account]");if(!button||!dcV3Root.contains(button))return;event.preventDefault();event.stopImmediatePropagation();const account=dcV3State.accounts.find(row=>row.promoter_id===decodeURIComponent(button.dataset.v3Account));if(account)dcV3LoadAccount(account);else{dcV3State.detailError="该渠道账号缺少稳定的推广员归属标识，无法打开下钻。";dcV3Render()}};dcV3Root.__dcV3AccountClick=handler;dcV3Root.addEventListener("click",handler,true)}
function dcV3PointDiff(x){if(x.point_diff==null)return "--";return `<span class="point-diff" tabindex="0" data-tooltip="${dcV3Pct(x.access_point)} - ${dcV3Pct(x.release_point)}">${dcV3Pct(x.point_diff)}</span>`}
function dcV3ClientExport(filename,columns,rows){const esc=v=>{const s=String(v==null?"":v);return /[",\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s};const csv="\ufeff"+[columns.map(x=>esc(x.title)).join(","),...rows.map(row=>columns.map(x=>esc(row[x.key])).join(","))].join("\n");const blob=new Blob([csv],{type:"text/csv;charset=utf-8"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=filename+".csv";a.click();URL.revokeObjectURL(url)}
function dcV3ShareChart(){const unavailable=!dcV3State.share.length||dcV3State.share.some(x=>x.metric_status==="SOURCE_NOT_AVAILABLE");if(unavailable)return "当前指标源暂不可用";const rows=dcV3State.share.map(x=>({name:x.channel_name||x.channel_id,value:dcV3Num(x[dcV3State.metric])})).filter(x=>x.value>0),total=rows.reduce((a,x)=>a+x.value,0);if(!total)return "当前期间暂无可展示指标";const colors=["#1677ff","#36cfc9","#73d13d","#ffc53d","#ff7a45","#9254de","#5cdbd3"];let cursor=0;const stops=rows.map((x,i)=>{const start=cursor/total*100;cursor+=x.value;return `${colors[i%colors.length]} ${start}% ${cursor/total*100}%`}).join(",");return `<div class="demo-pie-layout"><div class="demo-donut" style="background:conic-gradient(${stops})"><div class="demo-donut-hole"><b>${dcV3State.metric==="revenue_amount"?dcV3Money(total):total.toLocaleString("zh-CN")}</b><span>${dcV3State.metric==="revenue_amount"?"渠道流水":"注册账号"}</span></div></div><div class="demo-legend">${rows.map((x,i)=>`<div><i style="background:${colors[i%colors.length]}"></i><span>${x.name}</span><em>${dcV3State.metric==="revenue_amount"?dcV3Money(x.value):x.value.toLocaleString("zh-CN")}</em></div>`).join("")}</div></div>`}
function dcV3BenchmarkChart(){const unavailable=!dcV3State.benchmark.length||dcV3State.benchmark.some(x=>x.metric_status==="SOURCE_NOT_AVAILABLE");if(unavailable)return "聚玩基准源暂不可用";const rows=dcV3State.benchmark.map(x=>({name:x.channel_name||x.channel_id,value:dcV3Num(x[dcV3State.metric]),ratio:x.ratio==null?null:Number(x.ratio)})).filter(x=>x.value>0),max=Math.max(...rows.map(x=>x.ratio||x.value),100);if(!rows.length)return "当前期间暂无可比较指标";return `<div class="demo-benchmark"><div class="benchmark-scale"><span>0%</span><span>50%</span><span>100%</span></div>${rows.map(x=>`<div class="benchmark-row"><b>${x.name}</b><div class="benchmark-track"><i style="width:${Math.min(100,(x.ratio==null?x.value/max*100:x.ratio))}%;background:#36cfc9"></i></div><span>${dcV3State.metric==="revenue_amount"?dcV3Money(x.value):x.value.toLocaleString("zh-CN")}${x.ratio==null?"":" · "+x.ratio+"%"}</span></div>`).join("")}<div class="benchmark-note">基准值或来源不可用时不填充对比数据</div></div>`}
function dcV3Trend(t){const max=Math.max(...t.map(x=>dcV3Num(x.revenue_amount)),1);return `<div class="panel-title">渠道收益趋势 <span class="legend right"><span><i class="dot"></i>渠道流水</span><span><i class="dot cost"></i>应结出</span></span></div><div class="chart chart-full">${t.map(x=>`<div class="bar-group"><div class="bar" style="height:${Math.max(4,dcV3Num(x.revenue_amount)/max*170)}px" title="流水 ${dcV3Money(x.revenue_amount)}"></div>${x.settlement_out_amount==null?"":`<div class="bar cost" style="height:${Math.max(4,dcV3Num(x.settlement_out_amount)/max*170)}px" title="应结 ${dcV3Money(x.settlement_out_amount)}"></div>`}<span class="bar-label">${x.business_date||x.date||""}</span></div>`).join("")||`<div class="empty">当前期间暂无趋势数据</div>`}</div>`}
function dcV3ProjectHead(label,key){return `<button class="sort-button" data-v3-sort="${key}">${label}<span class="sort-mark ${dcV3State.projectSortKey===key?"active":""}">${dcV3SortIndicator(key)}</span></button>`}
function dcV3ProjectGroups(){const groups=new Map;dcV3State.projects.forEach(row=>{let item=groups.get(row.project_id);if(!item){item={...row,package_count:0,account_count:0,registration_count:0,revenue_amount:0,settlement_out_amount:0,payer_count:0};groups.set(row.project_id,item)}item.package_count+=1;item.account_count=Math.max(item.account_count,dcV3Num(row.project_account_count==null?row.account_count:row.project_account_count));item.registration_count+=dcV3Num(row.registration_count);item.revenue_amount+=dcV3Num(row.revenue_amount);item.settlement_out_amount+=dcV3Num(row.settlement_out_amount);item.payer_count+=dcV3Num(row.payer_count);if(row.data_status==="PARTIAL")item.data_status="PARTIAL"});return Array.from(groups.values()).map(item=>({...item,arpu:item.registration_count?item.revenue_amount/item.registration_count:null,arppu:item.payer_count?item.revenue_amount/item.payer_count:null}))}
function dcV3ProjectGroup(projectId){return dcV3ProjectGroups().find(row=>row.project_id===projectId)||null}
function dcV3Package(){const project=dcV3State.selectedProject||{},rows=dcV3State.projects.filter(row=>row.project_id===project.project_id),summary={account_count:rows.reduce((sum,row)=>sum+dcV3Num(row.account_count),0),registration_count:rows.reduce((sum,row)=>sum+dcV3Num(row.registration_count),0),revenue_amount:rows.reduce((sum,row)=>sum+dcV3Num(row.revenue_amount),0),settlement_out_amount:rows.reduce((sum,row)=>sum+dcV3Num(row.settlement_out_amount),0)};return dcV3Layout(`<div class="page-head"><button class="back" id="v3BackDetail">← 返回项目列表</button><h1>${project.project_name||project.project_id||"项目"} · 包体列表</h1><span class="prototype-flag">V9真实数据</span><span class="meta">${dcV3PeriodLabel()}</span></div><div class="definition"><strong>下钻路径</strong><span>点击具体包体后，仅进入该包体对应的渠道账号页面。</span></div><section class="kpis"><div class="kpi"><label>包体数</label><b>${rows.length}</b><small>当前项目</small></div><div class="kpi"><label>渠道账号数</label><b>${summary.account_count}</b><small>按包体范围统计</small></div><div class="kpi"><label>渠道流水</label><b>${dcV3Money(summary.revenue_amount)}</b><small>当前筛选区间</small></div><div class="kpi"><label>应结出流水</label><b>${dcV3Money(summary.settlement_out_amount)}</b><small>按放出点位汇总</small></div></section><section class="panel ranking-panel"><div class="ranking-head"><strong>包体数据排行</strong><div class="ranking-tools">${dcV3Dates()}</div></div><div class="ranking-scroll"><table class="ranking-table"><thead><tr><th>排序</th><th>包体</th><th>方向</th><th>渠道账号数</th><th>注册账号</th><th>渠道流水</th><th>应结出流水</th><th>放出点位</th><th>数据状态</th></tr></thead><tbody>${dcV3SortRows(rows,dcV3State.projectSortKey,dcV3State.projectSortDirection).map((row,index)=>`<tr><td>${index+1}</td><td><button class="project-link" data-v3-package="${dcV3Esc(row.package_id||"")}">${row.package_name||row.package_id||"--"}</button></td><td>${row.direction||"--"}</td><td>${row.account_count==null?"--":row.account_count}</td><td>${row.registration_count==null?"--":row.registration_count}</td><td>${dcV3Money(row.revenue_amount)}</td><td>${dcV3Money(row.settlement_out_amount)}</td><td>${dcV3Pct(row.release_point)}</td><td><span class="pill ${row.data_status==="PARTIAL"?"warn":"good"}">${dcV3StatusLabel(row.data_status)}</span></td></tr>`).join("")||`<tr><td colspan="9"><div class="empty">当前项目暂无包体数据</div></td></tr>`}</tbody></table></div></section>`)}
function dcV3Detail(){const x=dcV3State.selected||{},rows=dcV3State.projects,sm=dcV3Summary(dcV3State.projectPayload||{});return dcV3Layout(`<div class="page-head"><button class="back" id="v3Back">← 返回渠道列表</button><h1>${x.channel_name||x.channel_id||"渠道"} · 渠道收益详情</h1><span class="prototype-flag">V9真实数据</span><span class="meta">${dcV3PeriodLabel()}</span></div><div class="definition"><strong>归属依据</strong><span>使用显式渠道关系，按渠道账号 → 项目 → 注册/充值事实 → 区间汇总；未知方向、点位版本和待映射事实按契约隔离。</span><button id="showLineage">查看数据链路</button></div><div class="dc-v3-detail-notice">${dcV3State.detailError?`<div class="dc-proto-notice warn">${dcV3State.detailError}</div>`:""}${dcV3Notice(dcV3Meta(dcV3State.projectPayload||{}))}</div><section class="kpis"><div class="kpi"><label>区间渠道流水</label><b>${dcV3Money(sm.revenue_amount)}</b><small>当前筛选区间</small></div><div class="kpi"><label>区间应结出流水</label><b>${dcV3Money(sm.settlement_out_amount)}</b><small>已确认放出点位</small></div><div class="kpi"><label>区间注册账号</label><b>${sm.registration_count||0}</b><small>账号注册去重</small></div><div class="kpi"><label>渠道账号数</label><b>${sm.account_count||0}</b><small>${sm.project_count||rows.length} 个项目</small></div></section><div class="toolbar compact-filter">${dcV3Dates()}</div><section class="panel">${dcV3Trend(dcV3State.trend)}</section><section class="panel ranking-panel"><div class="ranking-head"><strong>项目数据排行</strong><span>汇总=区间去重（跨账号只计一次）</span><div class="ranking-tools"><button class="export-outline" id="v3ProjectExport">⇩ 导出</button></div></div>${dcV3ProjectTable(rows,sm)}</section>`)}
function dcV3Project(){const p=dcV3State.selectedProject||{},rows=dcV3State.accounts,sm=dcV3Summary(dcV3State.accountPayload||{});return dcV3Layout(`<div class="page-head"><button class="back" id="v3BackDetail">← 返回${dcV3State.selected&&dcV3State.selected.channel_name||"渠道"}渠道详情</button><h1>${p.project_name||p.project_id||"项目"} · ${p.package_name||p.package_id||"包体"} · 渠道账号详情</h1><span class="prototype-flag">V9真实数据</span><span class="meta">${dcV3PeriodLabel()}</span></div><div class="definition"><strong>账号范围</strong><span>仅展示渠道归属为“${dcV3State.selected&&dcV3State.selected.channel_name||"当前渠道"}”、归属项目为“${p.project_name||p.project_id||"当前项目"}”且归属包体为“${p.package_name||p.package_id||"当前包体"}”的渠道账号；其他包体不进入本页。</span><button id="showAccountRule">查看口径</button></div>${dcV3State.detailError?`<div class="dc-proto-notice warn">${dcV3State.detailError}</div>`:""}${dcV3Notice(dcV3Meta(dcV3State.accountPayload||{}))}<section class="kpis"><div class="kpi"><label>渠道账号数</label><b>${sm.account_count==null?rows.length:sm.account_count}</b><small>${dcV3State.selected&&dcV3State.selected.channel_name||"渠道"} · ${p.project_name||p.project_id||"项目"} · ${p.package_name||p.package_id||"包体"}</small></div><div class="kpi"><label>注册账号</label><b>${sm.registration_count==null?rows.reduce((a,x)=>a+dcV3Num(x.registration_count),0):sm.registration_count}</b><small>当前筛选区间去重</small></div><div class="kpi"><label>渠道流水</label><b>${dcV3Money(sm.revenue_amount==null?rows.reduce((a,x)=>a+dcV3Num(x.revenue_amount),0):sm.revenue_amount)}</b><small>当前筛选区间</small></div><div class="kpi"><label>应结出流水</label><b>${dcV3Money(sm.settlement_out_amount==null?rows.reduce((a,x)=>a+dcV3Num(x.settlement_out_amount),0):sm.settlement_out_amount)}</b><small>按账号放出点位汇总</small></div></section><section class="panel ranking-panel"><div class="ranking-head"><strong>渠道账号数据排行</strong><div class="ranking-tools">${dcV3Dates()}<small>汇总=区间去重</small><button class="export-outline" id="v3AccountExport">⇩ 导出</button></div></div><div class="ranking-scroll"><table class="ranking-table"><thead><tr><th>排序</th><th>渠道账号</th><th>注册账号</th><th>渠道流水</th><th>放出点位</th><th>应结出流水</th><th>ARPU</th><th>ARPPU</th><th>数据状态</th></tr></thead><tbody>${rows.map((x,i)=>`<tr><td>${i+1}</td><td><button class="account-link" data-v3-account="${dcV3Esc(x.promoter_id)}">${x.promoter_account||x.account_key||x.promoter_id}</button></td><td>${x.registration_count||0}</td><td>${dcV3Money(x.revenue_amount)}</td><td>${dcV3Pct(x.release_point)}</td><td>${dcV3Money(x.settlement_out_amount)}</td><td>${dcV3Money(x.arpu)}</td><td>${dcV3Money(x.arppu)}</td><td><span class="pill ${x.data_status==="PARTIAL"?"warn":"good"}">${dcV3StatusLabel(x.data_status)}</span></td></tr>`).join("")||`<tr><td colspan="9"><div class="empty">当前期间暂无渠道账号数据</div></td></tr>`}</tbody></table></div></section>`)}
function dcV3MetricValue(summary,key){const item=(summary.metrics||[]).find(x=>x.key===key);return item?item.value:summary[key]}
function dcV3AccountDaily(rows){rows=rows.slice().sort((a,b)=>String(b.date||b.business_date||"").localeCompare(String(a.date||a.business_date||"")));return `<section class="panel ranking-panel"><div class="ranking-head"><strong>基础数据报表</strong><div class="ranking-tools">${dcV3Dates()}<small>汇总=当前筛选区间口径</small><button class="export-outline" data-v3-export="daily">⇩ 导出</button></div></div><div class="ranking-scroll"><table class="ranking-table"><thead><tr><th>日期</th><th>新账号</th><th>新付费数</th><th>新付费总额</th><th>新付费率</th><th>活跃</th><th>付费数</th><th>付费总额</th><th>付费率</th><th>ARPU</th><th>ARPPU</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${x.date||x.business_date||"--"}</td><td>${x.new_account_count||0}</td><td>${x.new_paid_count||0}</td><td>${dcV3Money(x.new_paid_amount)}</td><td>${dcV3Pct(x.new_paid_rate)}</td><td>${x.active_account_count==null?"--":x.active_account_count}</td><td>${x.paid_count||0}</td><td>${dcV3Money(x.paid_amount)}</td><td>${dcV3Pct(x.paid_rate)}</td><td>${dcV3Money(x.arpu)}</td><td>${dcV3Money(x.arppu)}</td></tr>`).join("")||`<tr><td colspan="11"><div class="empty">当前期间暂无基础数据</div></td></tr>`}</tbody></table></div></section>`}
function dcV3Account(){const d=dcV3State.accountData||{},s=d.summary||{},regs=dcV3Rows(d.registrations),recharges=dcV3Rows(d.recharges),trend=dcV3Rows(d.trend),specs=[["new_account_count","新账号数","当前筛选区间"],["new_paid_count","新账号付费数","当前筛选区间"],["new_paid_amount","新账号付费总额","当前筛选区间"],["registration_count","当期注册账号总数","当前筛选区间去重"],["active_account_count","活跃账号数","活跃源暂不可用"],["paid_count","账号付费数","当前筛选区间"],["paid_amount","账号付费总额","当前筛选区间"],["period_paid_amount","当期付费总额","当前筛选区间"]];return dcV3Layout(`<div class="page-head"><button class="back" id="v3BackProject">← 返回项目账号</button><h1>${s.promoter_account||dcV3State.selectedAccount&&dcV3State.selectedAccount.promoter_account||dcV3State.selectedAccount&&dcV3State.selectedAccount.promoter_id||"渠道账号"} · 推广员详情</h1><span class="prototype-flag">V9真实数据</span><span class="meta">${dcV3PeriodLabel()}</span></div><div class="definition"><strong>所属项目</strong><span>${s.project_name||dcV3State.selectedProject&&dcV3State.selectedProject.project_name||"--"}　·　渠道归属：${dcV3State.selected&&dcV3State.selected.channel_name||"--"}</span><button id="showAccountLineage">查看归属链路</button></div>${dcV3State.detailError?`<div class="dc-proto-notice warn">${dcV3State.detailError}</div>`:""}${dcV3Notice(dcV3Meta(d.summaryPayload||{}))}<section class="kpis account-kpis">${specs.map(([key,label,note])=>{const value=dcV3MetricValue(s,key),amount=key.includes("amount"),status=key==="active_account_count"&&value==null?"指标源暂不可用":note;return `<div class="kpi"><label>${label}</label><b>${value==null?"--":amount?dcV3Money(value):value}</b><small>${status}</small></div>`}).join("")}</section>${dcV3AccountDaily(trend)}<section class="panel ranking-panel"><div class="ranking-head"><strong>注册明细</strong><div class="ranking-tools"><button class="export-outline" data-v3-export="registrations">⇩ 导出</button></div></div><div class="ranking-scroll"><table class="ranking-table registration-table"><thead><tr><th>用户ID</th><th>用户名</th><th>小号</th><th>推广代理</th><th>注册包体</th><th>服务器</th><th>注册时间</th><th>注册设备</th><th>数据来源</th></tr></thead><tbody>${regs.map(x=>`<tr><td>${x.user_id||"--"}</td><td>${x.user_name||"--"}</td><td>${x.sub_account||"--"}</td><td>${x.promoter_account||s.promoter_account||"--"}</td><td>${x.package||"--"}</td><td>${x.server||"--"}</td><td>${x.registered_at||x.registration_time||"--"}</td><td>${x.device_type||x.device||"--"}</td><td>${x.source_platform||x.source||"--"}</td></tr>`).join("")||`<tr><td colspan="9"><div class="empty">暂无注册明细</div></td></tr>`}</tbody></table></div></section><section class="panel"><div class="panel-title">${s.project_name||"项目"} · ${s.promoter_account||"渠道账号"} · 数据趋势</div><div class="mini-trend">${trend.map(x=>`<div class="trend-column"><div class="trend-line" style="height:${Math.max(8,dcV3Num(x.recharge_amount||x.revenue_amount)/Math.max(...trend.map(y=>dcV3Num(y.recharge_amount||y.revenue_amount)),1)*145)}px" title="${dcV3Money(x.recharge_amount||x.revenue_amount)}"></div><span>${String(x.date||x.business_date||"").slice(5)}</span></div>`).join("")||`<div class="empty">当前期间暂无趋势数据</div>`}</div></section><section class="panel ranking-panel"><div class="ranking-head"><strong>充值明细（一级平台口径）</strong><div class="ranking-tools"><button class="export-outline" data-v3-export="recharges">⇩ 导出</button></div></div><div class="ranking-scroll"><table class="ranking-table order-table"><thead><tr><th>订单号</th><th>用户名</th><th>推广代理</th><th>服务器</th><th>角色名</th><th>实际支付</th><th>充值方式</th><th>支付时间</th><th>支付状态</th></tr></thead><tbody>${recharges.map(x=>`<tr><td>${x.order_id||"--"}</td><td>${x.user_name||"--"}</td><td>${x.promoter_account||s.promoter_account||"--"}</td><td>${x.server||"--"}</td><td>${x.role_name||"--"}</td><td>${dcV3Money(x.pay_amount)}</td><td>${x.payment_method||"--"}</td><td>${x.paid_at||x.payment_time||"--"}</td><td>${x.payment_status||x.status||"--"}</td></tr>`).join("")||`<tr><td colspan="9"><div class="empty">暂无充值明细</div></td></tr>`}</tbody></table></div></section>`)}
async function dcV3LoadList(){if(dcV3Abort)dcV3Abort.abort();dcV3Abort=new AbortController();const seq=++dcV3Seq;dcV3State.view="list";dcV3State.loading=true;dcV3State.error=null;dcV3Render();const q=dcV3Query({date_from:dcV3State.dateFrom,date_to:dcV3State.dateTo,page:1,page_size:100,sort_by:"revenue_amount",sort_order:"desc"});try{const main=await dcV3Fetch("/api/v1/channel-detail-v9/channels?"+q,{signal:dcV3Abort.signal});if(seq!==dcV3Seq)return;dcV3State.channels=dcV3Rows(main);dcV3State.share=dcV3State.channels;dcV3State.benchmark=[{metric_status:"SOURCE_NOT_AVAILABLE"}];dcV3State.meta=dcV3Meta(main);dcV3State.summary=dcV3Summary(main);dcV3State.loading=false;dcV3Url();dcV3Render()}catch(e){if(e.name==="AbortError")return;if(seq!==dcV3Seq)return;dcV3State.loading=false;dcV3State.error=dcV3Error(e);dcV3Render()}}
async function dcV3LoadDetail(channel){const seq=++dcV3Seq;dcV3State.view="detail";dcV3State.detailLoading=true;dcV3State.detailError=null;dcV3Render();const q=dcV3Query({date_from:dcV3State.dateFrom,date_to:dcV3State.dateTo});try{const [trend,projects]=await Promise.all([dcV3Fetch("/api/v1/channel-detail-v9/channels/"+dcV3Esc(channel.channel_id)+"/trend?"+q),dcV3Fetch("/api/v1/channel-detail-v9/channels/"+dcV3Esc(channel.channel_id)+"/projects?"+q)]);if(seq!==dcV3Seq)return false;dcV3State.trend=dcV3Rows(trend);dcV3State.projectPayload=projects;dcV3State.projects=dcV3Rows(projects);dcV3State.detailLoading=false;dcV3Url();dcV3Render();return true}catch(e){if(seq!==dcV3Seq)return false;dcV3State.detailLoading=false;dcV3State.detailError=dcV3Error(e);dcV3Render();return false}}
async function dcV3LoadProject(project){const seq=++dcV3Seq;dcV3State.detailError=null;dcV3State.view="project";dcV3State.detailLoading=true;dcV3State.accounts=[];dcV3Render();try{const data=await dcV3Fetch("/api/v1/channel-detail-v9/channels/"+dcV3Esc(dcV3State.selected.channel_id)+"/projects/"+dcV3Esc(project.project_id)+"/accounts?"+dcV3Query({date_from:dcV3State.dateFrom,date_to:dcV3State.dateTo,package_id:project.package_id,page:1,page_size:100}));if(seq!==dcV3Seq)return false;dcV3State.accounts=dcV3Rows(data);dcV3State.accountPayload=data;dcV3State.detailLoading=false;dcV3Url();dcV3Render();return true}catch(e){if(seq!==dcV3Seq)return false;dcV3State.detailLoading=false;dcV3State.detailError=dcV3Error(e);dcV3Render();return false}}
async function dcV3LoadAccount(account){const seq=++dcV3Seq;dcV3State.view="account";dcV3State.selectedAccount=account;dcV3State.accountData=null;dcV3State.detailLoading=true;dcV3State.detailError=null;dcV3Render();const base="/api/v1/channel-detail-v9/promoters/"+dcV3Esc(account.promoter_id),q=dcV3Query({date_from:dcV3State.dateFrom,date_to:dcV3State.dateTo,channel_id:dcV3State.selected.channel_id,project_id:dcV3State.selectedProject.project_id});try{const [summary,trend,registrations,recharges]=await Promise.all([dcV3Fetch(base+"/summary?"+q),dcV3Fetch(base+"/trend?"+q),dcV3Fetch(base+"/registrations?"+q),dcV3Fetch(base+"/recharges?"+q)]);if(seq!==dcV3Seq)return false;dcV3State.accountData={summary:summary.data||summary,summaryPayload:summary,trend:trend,registrations:registrations,recharges:recharges};dcV3State.detailLoading=false;dcV3Url();dcV3Render();return true}catch(e){if(seq!==dcV3Seq)return false;dcV3State.detailLoading=false;dcV3State.detailError=dcV3Error(e);dcV3Render();return false}}
async function dcV3ReloadCurrent(){if(dcV3State.view==="list"||!dcV3State.selected)return dcV3LoadList();const view=dcV3State.view,projectId=dcV3State.selectedProject&&dcV3State.selectedProject.project_id,packageId=dcV3State.selectedProject&&dcV3State.selectedProject.package_id,promoterId=dcV3State.selectedAccount&&dcV3State.selectedAccount.promoter_id;if(!await dcV3LoadDetail(dcV3State.selected)||view==="detail")return;dcV3State.selectedProject=dcV3State.projects.find(x=>x.project_id===projectId&&(x.package_id||"")===(packageId||""))||null;if(!dcV3State.selectedProject||!await dcV3LoadProject(dcV3State.selectedProject)||view==="project")return;dcV3State.selectedAccount=dcV3State.accounts.find(x=>x.promoter_id===promoterId)||null;if(dcV3State.selectedAccount)await dcV3LoadAccount(dcV3State.selectedAccount)}
async function dcV3Export(kind){const account=dcV3State.selectedAccount;if(!account)return;try{const body={kind,promoter_id:account.promoter_id,channel_id:dcV3State.selected.channel_id,project_id:dcV3State.selectedProject.project_id,date_from:dcV3State.dateFrom,date_to:dcV3State.dateTo};const created=await dcV3Fetch("/api/v1/channel-detail-v9/exports",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)}),id=dcV3Data(created).job_id||created.job_id,ready=await dcV3Fetch("/api/v1/channel-detail-v9/exports/"+dcV3Esc(id)),r=await fetch(dcV3ApiBase+(dcV3Data(ready).download_url||ready.download_url),{credentials:"same-origin"});if(!r.ok)throw new Error("导出下载失败");const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=dcV3Data(ready).filename||"channel-detail.csv";a.click();URL.revokeObjectURL(url)}catch(e){dcV3State.detailError=dcV3Error(e);dcV3Render()}}
function dcV3Render(){if(!dcV3Root)return;if(dcV3DateRoot){try{dcV3DateRoot.unmount()}catch(e){}dcV3DateRoot=null}const body=dcV3State.loading&&dcV3State.view==="list"?`<div class="empty">正在加载 V9 真实数据…</div>`:dcV3State.view==="list"?dcV3List():dcV3State.view==="detail"?(dcV3State.detailLoading?`<div class="empty">正在加载渠道下钻…</div>`:dcV3Detail()):dcV3State.view==="project"?(dcV3State.detailLoading?`<div class="empty">正在加载渠道账号…</div>`:dcV3Project()):(dcV3State.detailLoading?`<div class="empty">正在加载推广员明细…</div>`:dcV3Account());dcV3Root.innerHTML=body;dcV3Bind();dcV3MountDatePicker();dcV3ApplyFieldTips();dcV3EnsurePromoterNameColumn();dcV3InstallTooltips();dcV3InstallAccountClick()}
function dcV3Mount(root){dcV3Root=root;const q=dcV3InitDates(),channelId=q.get("channel_id"),projectId=q.get("project_id"),packageId=q.get("package_id")||"",promoterId=q.get("promoter_id");dcV3Render();(async()=>{await dcV3LoadList();if(!channelId)return;dcV3State.selected=dcV3State.channels.find(r=>r.channel_id===channelId)||null;if(!dcV3State.selected||!await dcV3LoadDetail(dcV3State.selected)||!projectId)return;dcV3State.selectedProject=dcV3State.projects.find(r=>r.project_id===projectId&&(r.package_id||"")===packageId)||null;if(!dcV3State.selectedProject||!await dcV3LoadProject(dcV3State.selectedProject)||!promoterId)return;dcV3State.selectedAccount=dcV3State.accounts.find(r=>r.promoter_id===promoterId)||null;if(dcV3State.selectedAccount)await dcV3LoadAccount(dcV3State.selectedAccount)})();return()=>{if(dcV3Abort)dcV3Abort.abort();dcV3DestroyTooltips(root);dcV3Root=null}}
// Route-only field alignment: channel alias, platform and legal subject stay separate.
let dcV3Notice,dcV3List,dcV3ProjectTable,dcV3Bind;

dcV3Notice=function(meta){const parts=[];if(Number(meta.unmapped_channel_count||0))parts.push("待映射渠道 "+meta.unmapped_channel_count);if(Number(meta.unmapped_project_count||0))parts.push("待映射项目 "+meta.unmapped_project_count);if(Number(meta.orphan_recharge_count||0))parts.push("孤儿充值 "+meta.orphan_recharge_count);if(Number(meta.unknown_point_version_count||0))parts.push("点位版本未知 "+meta.unknown_point_version_count);if(Number(meta.unknown_registration_direction_count||0))parts.push("注册方向未知 "+meta.unknown_registration_direction_count);if(Number(meta.promoter_account_missing_count||0))parts.push("推广员账号为空 "+meta.promoter_account_missing_count);if(Number(meta.account_mapping_missing_count||0))parts.push("账号未在映射表 "+meta.account_mapping_missing_count);if(Number(meta.platform_mapping_mismatch_count||0))parts.push("平台不一致 "+meta.platform_mapping_mismatch_count);if(Number(meta.account_mapping_ambiguous_count||0))parts.push("账号归属歧义 "+meta.account_mapping_ambiguous_count);if(Number(meta.channel_detail_mapping_missing_count||0)){const aliases=(meta.channel_detail_mapping_missing_aliases||[]).join("、")||"未命名";parts.push("渠道详情缺失 "+aliases+"（"+meta.channel_detail_mapping_missing_count+"条）")}const gs=Number(meta.excluded_gs_reuse_count||0);const non=Number(meta.excluded_non_channel_count||0);return `<div class="dc-proto-notice ${meta.partial?"warn":"ok"}"><b>${meta.partial?"PARTIAL · 部分数据已隔离":"数据完整性正常"}</b><span>数据更新：${meta.data_updated_at||"--"}</span>${parts.length?`<span>${parts.join("；")}</span>`:""}</div>${gs?`<div class="dc-proto-notice ok">GS复用已按契约隔离：${gs} 条，流水 ${dcV3Money(meta.excluded_gs_reuse_revenue_amount)}</div>`:""}${non?`<div class="dc-proto-notice ok">非外放渠道事实已隔离：${non} 条，未混入渠道经营列表</div>`:""}`}
dcV3List=function(){const rows=dcV3State.channels.filter(x=>(!dcV3State.search||(`${x.channel_name||""}${x.platform||""}${x.company_name||""}`).includes(dcV3State.search))),summary={channel_count:rows.length,revenue_amount:rows.reduce((a,x)=>a+dcV3Num(x.revenue_amount),0),registration_count:rows.reduce((a,x)=>a+dcV3Num(x.registration_count),0),account_count:rows.reduce((a,x)=>a+dcV3Num(x.account_count),0)};return dcV3Layout(`<div class="page-head"><span>⌘</span><h1>渠道详情</h1><span class="prototype-flag">V9真实数据</span><span class="meta">${dcV3PeriodLabel()}</span></div>${dcV3State.error?`<div class="dc-proto-notice warn">${dcV3State.error}</div>`:""}${dcV3Notice(dcV3State.meta||{})}<div class="definition"><strong>渠道口径</strong><span>渠道字段使用账号表“账号归属”的简称；平台单独取“平台方”。仅将渠道详情表中可对应到外放合作主体的简称列入列表，不能把平台当渠道。</span><button id="showListRule">查看完整规则</button></div><section class="kpis"><div class="kpi"><label>渠道归属方</label><b>${summary.channel_count||0}</b><small>简称 × 平台</small></div><div class="kpi"><label>区间渠道流水</label><b>${dcV3Money(summary.revenue_amount)}</b><small>账号归属匹配</small></div><div class="kpi"><label>区间注册账号</label><b>${summary.registration_count||0}</b><small>账号注册去重</small></div><div class="kpi"><label>区间应结出流水</label><b>${dcV3Money(rows.reduce((a,x)=>a+dcV3Num(x.settlement_out_amount),0))}</b><small>放出点位结算</small></div></section><div class="toolbar"><input id="v3Search" type="search" placeholder="搜索渠道简称、平台或合作主体" value="${dcV3State.search}"><span class="spacer"></span>${dcV3Dates()}<button class="primary" id="v3ListExport">导出</button></div><section class="panel"><div class="panel-title">渠道经营列表 <small>点击渠道名称进入收益下钻</small><span class="right">${rows.length} 个渠道维度</span></div><div class="table-wrap"><table><thead><tr><th>渠道</th><th>平台</th><th>合作主体</th><th>项目数</th><th>账号数</th><th>注册账号</th><th>渠道流水</th><th>应结出流水</th></tr></thead><tbody>${rows.map(x=>`<tr><td><button class="channel-link" data-v3-channel="${dcV3Esc(x.channel_id)}">${x.channel_name||x.channel_id}</button></td><td>${x.platform||"--"}</td><td>${x.company_name||"--"}</td><td>${x.project_count==null?"--":x.project_count}</td><td title="配置账号 ${x.configured_account_count==null?"--":x.configured_account_count}">${x.account_count==null?"--":x.account_count}</td><td>${x.registration_count==null?"--":x.registration_count}</td><td>${dcV3Money(x.revenue_amount)}</td><td>${dcV3Money(x.settlement_out_amount)}</td></tr>`).join("")||`<tr><td colspan="8"><div class="empty">当前期间没有可审计渠道指标</div></td></tr>`}</tbody></table></div></section><section class="analysis-grid"><div class="panel chart-panel"><div class="chart-head"><div><strong>渠道结构占比</strong><small>查看各渠道在总体中的构成</small></div><div class="metric-switch"><button data-v3-metric="registration_count" class="${dcV3State.metric==="registration_count"?"active":""}">注册账号</button><button data-v3-metric="revenue_amount" class="${dcV3State.metric==="revenue_amount"?"active":""}">渠道流水</button></div></div><div class="echart-box">${dcV3ShareChart()}</div></div><div class="panel chart-panel"><div class="chart-head"><div><strong>聚玩基准指数对比</strong><small>基准源不可用时显示不可用，不使用示例值</small></div></div><div class="echart-box">${dcV3BenchmarkChart()}</div></div></section>`)}
dcV3ProjectTable=function(rows,summary){
  const sorted=dcV3SortRows(rows,dcV3State.projectSortKey,dcV3State.projectSortDirection),totalRegs=dcV3Num(summary.registration_count),totalRevenue=dcV3Num(summary.revenue_amount),totalPayers=dcV3Num(summary.payer_count);
  return `<div class="ranking-scroll"><table class="ranking-table"><thead><tr><th>排序</th><th>${dcV3ProjectHead("项目名称","project_name")}</th><th>包体</th><th>方向</th><th>${dcV3ProjectHead("渠道账号数","account_count")}</th><th>${dcV3ProjectHead("注册账号","registration_count")}</th><th>${dcV3ProjectHead("渠道流水","revenue_amount")}</th><th>${dcV3ProjectHead("应结出流水","settlement_out_amount")}</th><th>接入点位</th><th>放出点位</th><th>点位差</th><th>ARPU</th><th>ARPPU</th><th>状态</th></tr></thead><tbody><tr class="summary-row"><td>汇总</td><td><strong>${summary.channel_name||"渠道"} · ${summary.platform||"平台"}汇总</strong></td><td>--</td><td>--</td><td>${summary.account_count||0}</td><td>${totalRegs}</td><td>${dcV3Money(totalRevenue)}</td><td>${dcV3Money(summary.settlement_out_amount)}</td><td>--</td><td>--</td><td>--</td><td>${totalRegs?dcV3Money(totalRevenue/totalRegs):"--"}</td><td>${totalPayers?dcV3Money(totalRevenue/totalPayers):"--"}</td><td>${dcV3StatusLabel(summary.data_status)}</td></tr>${sorted.map((x,i)=>`<tr><td>${i+1}</td><td><button class="project-link" data-v3-project="${dcV3Esc(x.project_id)}" data-v3-package="${dcV3Esc(x.package_id||"")}">${x.project_name||x.project_id}</button></td><td>${x.package_name||x.package_id||"--"}</td><td>${x.direction||"--"}</td><td>${x.account_count==null?"--":x.account_count}</td><td>${x.registration_count==null?"--":x.registration_count}</td><td>${dcV3Money(x.revenue_amount)}</td><td>${dcV3Money(x.settlement_out_amount)}</td><td>${dcV3Pct(x.access_point)}</td><td>${dcV3Pct(x.release_point)}</td><td>${dcV3PointDiff(x)}</td><td>${dcV3Money(x.arpu)}</td><td>${dcV3Money(x.arppu)}</td><td><span class="pill ${x.data_status==="PARTIAL"?"warn":"good"}">${dcV3StatusLabel(x.data_status)}</span></td></tr>`).join("")||`<tr><td colspan="14"><div class="empty">当前渠道尚未配置项目关系</div></td></tr>`}</tbody></table></div>`
}
dcV3Bind=function(){const q=id=>dcV3Root.querySelector(id);dcV3Root.querySelectorAll("[data-v3-channel]").forEach(b=>b.addEventListener("click",()=>{dcV3State.selected=dcV3State.channels.find(x=>x.channel_id===decodeURIComponent(b.dataset.v3Channel));dcV3State.selectedProject=null;dcV3State.selectedAccount=null;dcV3LoadDetail(dcV3State.selected)}));dcV3Root.querySelectorAll("[data-v3-metric]").forEach(b=>b.addEventListener("click",()=>{dcV3State.metric=b.dataset.v3Metric;dcV3Url();dcV3LoadList()}));q("#v3Back")?.addEventListener("click",()=>{dcV3State.view="list";dcV3State.selected=null;dcV3State.selectedProject=null;dcV3State.selectedAccount=null;dcV3Url();dcV3Render()});q("#v3BackDetail")?.addEventListener("click",()=>{dcV3State.view="detail";dcV3State.selectedProject=null;dcV3State.selectedAccount=null;dcV3Url();dcV3Render()});q("#v3BackProject")?.addEventListener("click",()=>{dcV3State.view="project";dcV3State.selectedAccount=null;dcV3Url();dcV3Render()});dcV3Root.querySelectorAll("[data-v3-project]").forEach(b=>b.addEventListener("click",()=>{dcV3State.selectedProject=dcV3State.projects.find(x=>x.project_id===decodeURIComponent(b.dataset.v3Project)&&(x.package_id||"")===decodeURIComponent(b.dataset.v3Package||""));dcV3State.selectedAccount=null;dcV3LoadProject(dcV3State.selectedProject)}));dcV3Root.querySelectorAll("[data-v3-account]").forEach(b=>b.addEventListener("click",()=>{dcV3State.selectedAccount=dcV3State.accounts.find(x=>x.promoter_id===decodeURIComponent(b.dataset.v3-account));dcV3LoadAccount(dcV3State.selectedAccount)}));dcV3Root.querySelectorAll("[data-v3-sort]").forEach(b=>b.addEventListener("click",()=>{const key=b.dataset.v3Sort;dcV3State.projectSortDirection=dcV3State.projectSortKey===key&&dcV3State.projectSortDirection==="desc"?"asc":"desc";dcV3State.projectSortKey=key;dcV3Render()}));q("#v3Search")?.addEventListener("input",e=>{dcV3State.search=e.target.value;dcV3Url();dcV3LoadList()});q("#v3DateFrom")?.addEventListener("change",e=>{dcV3State.dateFrom=e.target.value;dcV3Url();dcV3ReloadCurrent()});q("#v3DateTo")?.addEventListener("change",e=>{dcV3State.dateTo=e.target.value;dcV3Url();dcV3ReloadCurrent()});q("#showListRule")?.addEventListener("click",()=>{dcV3State.error="口径：渠道字段取账号归属简称，平台取平台方；最终列表只保留渠道详情表可对应的外放合作主体，缺失映射进入数据质量提示，不以 0 伪装。";dcV3Render()});q("#showLineage")?.addEventListener("click",()=>{dcV3State.detailError="归属链路：渠道关系 → 渠道简称 + 平台 → 项目 → 注册/充值事实 → 区间汇总。";dcV3Render()});q("#showAccountRule")?.addEventListener("click",()=>{dcV3State.detailError="账号范围：当前渠道 + 当前项目 + 当前包体的显式渠道账号，其他包体不进入本页。";dcV3Render()});q("#showAccountLineage")?.addEventListener("click",()=>{dcV3State.detailError=`归属链路：${dcV3State.selected&&dcV3State.selected.channel_name||"渠道"} → ${dcV3State.selectedProject&&dcV3State.selectedProject.project_name||"项目"} → ${dcV3State.selectedAccount&&dcV3State.selectedAccount.promoter_account||dcV3State.selectedAccount&&dcV3State.selectedAccount.promoter_id||"账号"}`;dcV3Render()});q("#v3ListExport")?.addEventListener("click",()=>dcV3ClientExport("渠道列表",[{key:"channel_name",title:"渠道"},{key:"platform",title:"平台"},{key:"company_name",title:"合作主体"},{key:"project_count",title:"项目数"},{key:"account_count",title:"账号数"},{key:"registration_count",title:"注册账号"},{key:"revenue_amount",title:"渠道流水"},{key:"settlement_out_amount",title:"应结出流水"}],dcV3State.channels));q("#v3ProjectExport")?.addEventListener("click",()=>dcV3ClientExport("项目排行",[{key:"project_name",title:"项目"},{key:"package_name",title:"包体"},{key:"direction",title:"方向"},{key:"account_count",title:"渠道账号数"},{key:"registration_count",title:"注册账号"},{key:"revenue_amount",title:"渠道流水"},{key:"settlement_out_amount",title:"应结出流水"},{key:"access_point",title:"接入点位"},{key:"release_point",title:"放出点位"},{key:"point_diff",title:"点位差"},{key:"arpu",title:"ARPU"},{key:"arppu",title:"ARPPU"},{key:"data_status",title:"状态"}],dcV3State.projects));q("#v3AccountExport")?.addEventListener("click",()=>dcV3ClientExport("渠道账号排行",[{key:"promoter_account",title:"渠道账号"},{key:"registration_count",title:"注册账号"},{key:"revenue_amount",title:"渠道流水"},{key:"release_point",title:"放出点位"},{key:"settlement_out_amount",title:"应结出流水"},{key:"arpu",title:"ARPU"},{key:"arppu",title:"ARPPU"},{key:"data_status",title:"数据状态"}],dcV3State.accounts));dcV3Root.querySelectorAll("[data-v3-export]").forEach(b=>b.addEventListener("click",()=>{const kind=b.dataset.v3Export;if(kind==="daily"){const rows=dcV3Rows(dcV3State.accountData&&dcV3State.accountData.trend);return dcV3ClientExport("基础数据报表",[{key:"date",title:"日期"},{key:"new_account_count",title:"新账号"},{key:"new_paid_count",title:"新付费数"},{key:"new_paid_amount",title:"新付费总额"},{key:"new_paid_rate",title:"新付费率"},{key:"active_account_count",title:"活跃"},{key:"paid_count",title:"付费数"},{key:"paid_amount",title:"付费总额"},{key:"paid_rate",title:"付费率"},{key:"arpu",title:"ARPU"},{key:"arppu",title:"ARPPU"}],rows)}dcV3Export(kind)}))}
dcV3Notice=function(meta){const parts=[];if(Number(meta.unmapped_channel_count||0))parts.push("待映射渠道 "+meta.unmapped_channel_count);if(Number(meta.unmapped_project_count||0))parts.push("待映射项目 "+meta.unmapped_project_count);if(Number(meta.orphan_recharge_count||0))parts.push("孤儿充值 "+meta.orphan_recharge_count);if(Number(meta.unknown_point_version_count||0))parts.push("点位版本未知 "+meta.unknown_point_version_count);if(Number(meta.unknown_registration_direction_count||0))parts.push("注册方向未知 "+meta.unknown_registration_direction_count);if(Number(meta.promoter_account_missing_count||0))parts.push("推广员账号为空 "+meta.promoter_account_missing_count);if(Number(meta.account_mapping_missing_count||0))parts.push("账号未在映射表 "+meta.account_mapping_missing_count);if(Number(meta.platform_mapping_mismatch_count||0))parts.push("平台不一致 "+meta.platform_mapping_mismatch_count);if(Number(meta.account_mapping_ambiguous_count||0))parts.push("账号归属歧义 "+meta.account_mapping_ambiguous_count);if(Number(meta.channel_detail_mapping_missing_count||0)){const aliases=(meta.channel_detail_mapping_missing_aliases||[]).join("、")||"未命名";parts.push("渠道详情缺失 "+aliases+"（"+meta.channel_detail_mapping_missing_count+"条）")}if(Number(meta.channel_detail_unmatched_company_count||0))parts.push("渠道主体无账号简称 "+(meta.channel_detail_unmatched_companies||[]).join("、"));if(Number(meta.account_aliases_without_channel_detail_count||0))parts.push("账号简称无渠道主体 "+(meta.account_aliases_without_channel_detail||[]).join("、"));const gs=Number(meta.excluded_gs_reuse_count||0),non=Number(meta.excluded_non_channel_count||0);return `<div class="dc-proto-notice ${meta.partial?"warn":"ok"}"><b>${meta.partial?"PARTIAL · 部分数据已隔离":"数据完整性正常"}</b><span>数据更新：${meta.data_updated_at||"--"}</span>${parts.length?`<span>${parts.join("；")}</span>`:""}</div>${gs?`<div class="dc-proto-notice ok">GS复用已按契约隔离：${gs} 条，流水 ${dcV3Money(meta.excluded_gs_reuse_revenue_amount)}</div>`:""}${non?`<div class="dc-proto-notice ok">非外放渠道事实已隔离：${non} 条，未混入渠道经营列表</div>`:""}`};

function dcV3ApplyBrowserReview(){
  if(!dcV3Root)return;
  const view=dcV3State.view;
  if(view==="list"){
    dcV3Root.querySelector(".definition")?.remove();
    if(!dcV3State.error)dcV3Root.querySelectorAll(".dc-proto-notice").forEach(node=>node.remove());
    const search=dcV3Root.querySelector("#v3Search");
    if(search){
      const localSearch=search.cloneNode(true);
      search.replaceWith(localSearch);
      localSearch.addEventListener("input",event=>{
        dcV3State.search=event.target.value;
        dcV3Url();
        clearTimeout(dcV3State.searchTimer);
        dcV3State.searchTimer=setTimeout(()=>dcV3Render(),120);
      });
    }
    dcV3Root.querySelectorAll("[data-v3-metric]").forEach(button=>{
      const localButton=button.cloneNode(true);
      button.replaceWith(localButton);
      localButton.addEventListener("click",()=>{
        dcV3State.metric=localButton.dataset.v3Metric;
        dcV3Url();
        dcV3Render();
      });
    });
  }
  if(view==="detail"){
    dcV3Root.querySelector(".definition")?.remove();
    const notice=dcV3Root.querySelector(".dc-v3-detail-notice");
    if(notice){
      if(dcV3State.detailError)Array.from(notice.querySelectorAll(".dc-proto-notice")).slice(1).forEach(node=>node.remove());
      else notice.remove();
    }
  }
  if(view==="package")dcV3Root.querySelector(".definition")?.remove();
  if(view==="project"){
    dcV3Root.querySelector(".definition")?.remove();
    const notices=Array.from(dcV3Root.querySelectorAll(".dc-proto-notice"));
    notices.slice(dcV3State.detailError?1:0).forEach(node=>node.remove());
  }
  if(view==="account"){
    const heading=Array.from(dcV3Root.querySelectorAll(".ranking-head")).find(node=>node.querySelector("strong")?.textContent.includes("充值明细"));
    const tools=heading&&heading.querySelector(".ranking-tools");
    if(tools&&!tools.querySelector("[data-v3-date-picker]")){
      tools.insertAdjacentHTML("afterbegin",dcV3Dates());
      dcV3MountDatePicker();
    }
  }
}

const dcV3InstallTooltipsBase=dcV3InstallTooltips;
dcV3InstallTooltips=function(){dcV3ApplyBrowserReview();dcV3InstallTooltipsBase()};

// Three-level drilldown: project -> package -> package accounts.
dcV3ProjectTable=function(rows,summary){const sorted=dcV3SortRows(dcV3ProjectGroups(),dcV3State.projectSortKey,dcV3State.projectSortDirection),totalRegs=dcV3Num(summary.registration_count),totalRevenue=dcV3Num(summary.revenue_amount),totalPayers=dcV3Num(summary.payer_count);return `<div class="ranking-scroll"><table class="ranking-table"><thead><tr><th>排序</th><th>${dcV3ProjectHead("项目名称","project_name")}</th><th>包体数</th><th>${dcV3ProjectHead("渠道账号数","account_count")}</th><th>${dcV3ProjectHead("注册账号","registration_count")}</th><th>${dcV3ProjectHead("渠道流水","revenue_amount")}</th><th>${dcV3ProjectHead("应结出流水","settlement_out_amount")}</th><th>ARPU</th><th>ARPPU</th><th>状态</th></tr></thead><tbody><tr class="summary-row"><td>汇总</td><td><strong>${summary.channel_name||"渠道"} · ${summary.platform||"平台"}汇总</strong></td><td>${sorted.reduce((sum,row)=>sum+row.package_count,0)}</td><td>${summary.account_count||0}</td><td>${totalRegs}</td><td>${dcV3Money(totalRevenue)}</td><td>${dcV3Money(summary.settlement_out_amount)}</td><td>${totalRegs?dcV3Money(totalRevenue/totalRegs):"--"}</td><td>${totalPayers?dcV3Money(totalRevenue/totalPayers):"--"}</td><td>${dcV3StatusLabel(summary.data_status)}</td></tr>${sorted.map((row,index)=>`<tr><td>${index+1}</td><td><button class="project-link" data-v3-project="${dcV3Esc(row.project_id)}">${row.project_name||row.project_id}</button></td><td>${row.package_count}</td><td>${row.account_count}</td><td>${row.registration_count}</td><td>${dcV3Money(row.revenue_amount)}</td><td>${dcV3Money(row.settlement_out_amount)}</td><td>${dcV3Money(row.arpu)}</td><td>${dcV3Money(row.arppu)}</td><td><span class="pill ${row.data_status==="PARTIAL"?"warn":"good"}">${dcV3StatusLabel(row.data_status)}</span></td></tr>`).join("")||`<tr><td colspan="10"><div class="empty">当前渠道尚未配置项目关系</div></td></tr>`}</tbody></table></div>`};

dcV3LoadProject=async function(packageRow){const seq=++dcV3Seq;dcV3State.selectedPackage=packageRow;dcV3State.detailError=null;dcV3State.view="project";dcV3State.detailLoading=true;dcV3State.accounts=[];dcV3Render();try{const data=await dcV3Fetch("/api/v1/channel-detail-v9/channels/"+dcV3Esc(dcV3State.selected.channel_id)+"/projects/"+dcV3Esc(dcV3State.selectedProject.project_id)+"/accounts?"+dcV3Query({date_from:dcV3State.dateFrom,date_to:dcV3State.dateTo,package_id:packageRow.package_id,page:1,page_size:100}));if(seq!==dcV3Seq)return false;dcV3State.accounts=dcV3Rows(data);dcV3State.accountPayload=data;dcV3State.detailLoading=false;dcV3Url();dcV3Render();return true}catch(e){if(seq!==dcV3Seq)return false;dcV3State.detailLoading=false;dcV3State.detailError=dcV3Error(e);dcV3Render();return false}};

