function dcV3InstallHierarchyClick(){if(!dcV3Root)return;const previous=dcV3Root.__dcV3HierarchyClick;if(previous)dcV3Root.removeEventListener("click",previous,true);const handler=event=>{const target=event.target&&event.target.closest&&event.target.closest("[data-v3-project],[data-v3-package],#v3BackPackage,#v3ProjectExport");if(!target||!dcV3Root.contains(target))return;if(target.matches("[data-v3-project]")){event.preventDefault();event.stopImmediatePropagation();dcV3OpenProject(decodeURIComponent(target.dataset.v3Project));return}if(target.matches("[data-v3-package]")){event.preventDefault();event.stopImmediatePropagation();const packageId=decodeURIComponent(target.dataset.v3Package||""),row=dcV3State.projects.find(item=>item.project_id===dcV3State.selectedProject.project_id&&(item.package_id||"")===packageId);if(row)dcV3LoadProject(row);return}if(target.id==="v3BackPackage"){event.preventDefault();event.stopImmediatePropagation();dcV3State.view="package";dcV3State.selectedPackage=null;dcV3State.selectedAccount=null;dcV3Url();dcV3Render();return}if(target.id==="v3ProjectExport"){event.preventDefault();event.stopImmediatePropagation();dcV3ClientExport("项目排行",[{key:"project_name",title:"项目"},{key:"package_count",title:"包体数"},{key:"account_count",title:"渠道账号数"},{key:"registration_count",title:"注册账号"},{key:"revenue_amount",title:"渠道流水"},{key:"settlement_out_amount",title:"应结出流水"},{key:"data_status",title:"状态"}],dcV3ProjectGroups())}};dcV3Root.__dcV3HierarchyClick=handler;dcV3Root.addEventListener("click",handler,true)}

